-- =========================================================================
-- SCRIPT NHẬP DỮ LIỆU GIA PHẢ TỘC VĂN VÀO SUPABASE (CHẠY 0 ĐỒNG)
-- Số lượng thành viên: 332 (Đời 1 đến Đời 9)
-- Nguồn: Bản thảo Gia Phả Tộc Văn cập nhật 20/7/2023
-- =========================================================================

-- 1. Bảng cấu hình Clan Info
CREATE TABLE IF NOT EXISTS clan_info (
  id TEXT PRIMARY KEY DEFAULT 'clan-main',
  clan_name TEXT NOT NULL,
  origin_province TEXT,
  ancestor_temple_address TEXT,
  description TEXT,
  total_generations INT DEFAULT 9,
  establishment_year TEXT,
  contact_person TEXT,
  contact_phone TEXT,
  contact_email TEXT,
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 2. Bảng Nhánh Phái (branches)
CREATE TABLE IF NOT EXISTS branches (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  code TEXT,
  description TEXT,
  color TEXT,
  leader_name TEXT,
  location TEXT,
  member_count INT DEFAULT 0
);

-- 3. Bảng Thành viên Gia phả (members)
CREATE TABLE IF NOT EXISTS members (
  id TEXT PRIMARY KEY,
  full_name TEXT NOT NULL,
  courtesy_name TEXT,
  posthumous_name TEXT,
  gender TEXT NOT NULL,
  generation INT NOT NULL,
  branch_id TEXT,
  phai_name TEXT,
  chi_name TEXT,
  nhanh_name TEXT,
  order_in_family INT DEFAULT 1,
  order_title TEXT,
  birth_place TEXT,
  birth_date TEXT,
  birth_date_lunar TEXT,
  is_alive BOOLEAN DEFAULT FALSE,
  death_date TEXT,
  death_date_lunar TEXT,
  burial_location TEXT,
  bio TEXT,
  father_id TEXT,
  mother_id TEXT,
  spouse_ids JSONB DEFAULT '[]'::jsonb,
  is_root_ancestor BOOLEAN DEFAULT FALSE,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Dữ liệu cấu hình Dòng tộc
INSERT INTO clan_info (id, clan_name, origin_province, ancestor_temple_address, description, total_generations, establishment_year, contact_person, contact_email) VALUES (
  'clan-main',
  'GIA PHẢ TỘC VĂN',
  'Quảng Nam',
  'Làng Mỹ Xuyên Tây, nay thuộc Thị trấn Nam Phước, huyện Duy Xuyên, tỉnh Quảng Nam',
  'Phả Hệ Tộc Văn (Văn Bá • Văn Tấn • Văn Phú) - Gốc tại Quảng Nam',
  9,
  '1680',
  'Ban Trị Sự Đại Tộc Văn',
  'sanhangdoc.shop@gmail.com'
) ON CONFLICT (id) DO UPDATE SET updated_at = NOW();

INSERT INTO branches (id, name, code, description, color, leader_name, location) VALUES (
  'branch-vbxt', 'Phái II - Xuyên Tây (VBXT)', 'PHAI-II-VBXT', 'Tộc Văn Bá – Làng cũ Mỹ Xuyên Tây, nay thuộc TT. Nam Phước, huyện Duy Xuyên, Quảng Nam. Thờ phụng Tổ tiên tại Từ Đường Tộc Văn Bá (TT. Nam Phước) và Nghĩa trang Gia tộc Gò Khoai.', 'undefined', '', ''
) ON CONFLICT (id) DO NOTHING;
INSERT INTO branches (id, name, code, description, color, leader_name, location) VALUES (
  'branch-vtqx', 'Phái II - Quế Xuân (VTQX)', 'PHAI-II-VTQX', 'Chi Tộc Văn Tấn – Quế Xuân, khởi từ ngài Ngũ thế Tiên tổ Văn Tấn Vinh tại làng cũ Xuân Phú, nay thuộc xã Quế Xuân, huyện Quế Sơn, Quảng Nam. Có Nhà thờ Tộc Văn Tấn tại Quế Xuân.', 'undefined', '', ''
) ON CONFLICT (id) DO NOTHING;
INSERT INTO branches (id, name, code, description, color, leader_name, location) VALUES (
  'branch-vbdl', 'Phái II - Đại Lộc (VBĐL)', 'PHAI-II-VBĐL', 'Chi Tộc Văn Bá – Đại Lộc (Chi Hà Nha), khởi từ ngài Ngũ thế Tiên tổ Văn Bá Hình tại làng cũ Hà Dục Đông, Hà Dục Tây, nay thuộc Đại Lộc, Quảng Nam. Nhà thờ Tộc tại Hà Nha, Đại Đồng.', 'undefined', '', ''
) ON CONFLICT (id) DO NOTHING;
INSERT INTO branches (id, name, code, description, color, leader_name, location) VALUES (
  'branch-vpxd', 'Phái III - Xuyên Đông (VPXĐ)', 'PHAI-III-VPXĐ', 'Chi Tộc Văn Phú – Xuyên Đông, khởi từ hai ngài Tuyên tổ Văn Phú Trạch và Văn Phú Súy tại làng cũ Mỹ Xuyên Đông, nay thuộc TT. Nam Phước, Duy Xuyên. Nhà thờ Chi Tộc Văn Phú tại Xuyên Đông.', 'undefined', '', ''
) ON CONFLICT (id) DO NOTHING;
INSERT INTO branches (id, name, code, description, color, leader_name, location) VALUES (
  'branch-vpxt', 'Phái IV - Xuyên Tây (VPXT)', 'PHAI-IV-VPXT', 'Chi Tộc Văn Phú – Xuyên Tây, khởi từ ngài Tuyên tổ Văn Phú Bơi tại làng cũ Mỹ Xuyên Tây, chung Nhà thờ Tộc Văn Phú tại Mỹ Xuyên Đông.', 'undefined', '', ''
) ON CONFLICT (id) DO NOTHING;
INSERT INTO branches (id, name, code, description, color, leader_name, location) VALUES (
  'branch-phai1', 'Phái I - Tiền Hiền (Trưởng Phái)', 'PHAI-I-VBXT', 'Phái I Văn Bá - Xuyên Tây: Con trưởng và cháu đích tôn của ngài Khải tổ mất sớm, mộ táng tại Cồn Đình, năm 1976 cải táng về Nghĩa trang Gia tộc Gò Khoai.', 'undefined', '', ''
) ON CONFLICT (id) DO NOTHING;

INSERT INTO members (id, full_name, courtesy_name, gender, generation, branch_id, phai_name, chi_name, nhanh_name, order_in_family, order_title, birth_place, is_alive, death_date_lunar, burial_location, bio, father_id, mother_id, spouse_ids, is_root_ancestor) VALUES (
  'mem-101',
  'Văn Bá Bạt',
  '1.0',
  'male',
  1,
  '',
  NULL,
  NULL,
  NULL,
  1,
  'Nhứt thế: Triệu Tổ (1.0)',
  'Làng Mỹ Xuyên, huyện Nông Cống, phủ Hà Trung, tỉnh Thanh Hóa (nay là xã Hà Vinh, huyện Hà Trung, Thanh Hóa)',
  FALSE,
  '10/03 ÂL',
  'Nghĩa trang Gia tộc tại Gò Khoai, xóm Mỹ Luân, TT. Nam Phước, huyện Duy Xuyên, Quảng Nam (cải táng 1976)',
  'Quê ở tỉnh Thanh Hóa, phủ Hà Trung, huyện Nông Cống, làng Mỹ Xuyên, địa diện núi Thần Phù. Nay là xã Hà Vinh, huyện Hà Trung, tỉnh Thanh Hóa. Mộ ông trước kia ở Thanh Hóa, con là ông Văn Bá Liêu sau khi lập nghiệp và ổn định ở Quảng Nam đã về quê cũ đem hài cốt cha trong một quách sành vào cải táng tại Cồn Đình, làng cũ Mỹ Xuyên Tây, nay thuộc Thị trấn Nam Phước, huyện Duy Xuyên. Năm 1976, cải táng lần 2 về nghĩa trang Gia tộc tại Gò Khoai, xóm Mỹ Luân, TT. Nam Phước.',
  NULL,
  NULL,
  '[]'::jsonb,
  TRUE
) ON CONFLICT (id) DO UPDATE SET full_name = EXCLUDED.full_name, bio = EXCLUDED.bio, burial_location = EXCLUDED.burial_location;

INSERT INTO members (id, full_name, courtesy_name, gender, generation, branch_id, phai_name, chi_name, nhanh_name, order_in_family, order_title, birth_place, is_alive, death_date_lunar, burial_location, bio, father_id, mother_id, spouse_ids, is_root_ancestor) VALUES (
  'mem-201',
  'Văn Bá Liêu',
  'Sử - Trình - Lư (2.0)',
  'male',
  2,
  '',
  NULL,
  NULL,
  NULL,
  1,
  'Nhị thế: Khải Tổ (2.0)',
  'Mỹ Xuyên Tây, TT. Nam Phước, Duy Xuyên, Quảng Nam',
  FALSE,
  '08/07 ÂL',
  'Nghĩa trang Gia tộc tại Gò Khoai, Xuyên Tây (cải táng 1976 từ Cồn Đình)',
  'Con ông Văn Bá Bạt. Tên ông thường gọi là: Sử - Trình - Lư. Khởi đầu lập nghiệp vững vàng tại làng cũ Mỹ Xuyên Tây, Duy Xuyên, Quảng Nam. Ngài đã thân hành về lại quê cũ Thanh Hóa mang quách sành đựng hài cốt thân phụ vào an táng tại Cồn Đình, mở rộng cơ nghiệp, lập Từ Đường Tộc Văn Bá tại Mỹ Xuyên Tây.',
  'mem-101',
  NULL,
  '["mem-201-w1","mem-201-w2"]'::jsonb,
  FALSE
) ON CONFLICT (id) DO UPDATE SET full_name = EXCLUDED.full_name, bio = EXCLUDED.bio, burial_location = EXCLUDED.burial_location;

