  'Thường gọi là Chỉnh Trai. Con ông Văn Bá Lục, cháu nội ông Văn Bá Liêu. Mộ ông bà song táng tại Cồn Đình, năm 1976 cải táng về nghĩa trang Gia tộc tại Gò Khoai. Sanh hạ 6 người con trai mở ra các chi nhánh lớn của Phái II: Văn Tấn Vinh (bắt đầu Phái II Tộc Văn Tấn - Quế Xuân), Văn Tấn Ba (Gia Định), Văn Bá Liễu, Văn Bá Hình (bắt đầu Phái II Tộc Văn Bá - Đại Lộc), Văn Bá Lý, Văn Bá Đình (kế tục Phái II Tộc Văn Bá - Xuyên Tây).',
