  'Thường gọi là Tiểu Triều. Con ông Văn Tấn Thành, cháu nội ông Văn Bá Lục. Ngài kế tục gia phả Tộc Văn Bá – Xuyên Tây và thờ phụng Tổ tiên từ ngài Triệu tổ xuống tại Nhà thờ Tộc Văn Bá TT. Nam Phước. Mộ trước táng tại Bàu Sen, năm 1976 cải táng về nghĩa trang Gia tộc tại Gò Khoai. Vợ là bà Trần Thị Hút (hiệu Thôn Khí, mất ngày 15/3 ÂL). Sanh hạ 5 con trai: Văn Bá Đồng, Văn Bá Trung (bắt đầu Chi 1), Văn Bá Trinh (mộ táng Gia Định), Văn Bá Trang, Văn Bá Đài (bắt đầu Chi 2).',
